# Security check before skill installation
def audit_skill(skill_path):
    suspicious_patterns = [
        'os.environ', '~/.env', 'webhook.site',
        'requests.post', 'urllib.request', 'http.client'
    ]
    with open(skill_path, 'r') as f:
        content = f.read()
        for pattern in suspicious_patterns:
            if pattern in content:
                return f"WARNING: Found {pattern} - manual review required"
    return "No obvious suspicious patterns"
